) AS (
  VALUES 
    (136::BIGINT, 'Excelente profesor, si bien el curso lo lleve por inclusion me gusto mucho, el profe se esmera en las clases y hace que uno le interesca el tema.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-10-14T00:00:00+00:00'::TIMESTAMPTZ, '122d319a4cb4c31747d3d9270524ff6e5f085e7810705e53571e4545429e90f9'::TEXT, ARRAY[3135]::BIGINT[]),
    (136::BIGINT, 'Pase el curso haciendo todo con IA, es demasiado fácil pasar con ese profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'b90603ae3078cf6c204b4efda9f530b829724c3e101eb424a3eb87882071e10e'::TEXT, ARRAY[981]::BIGINT[]),
    (136::BIGINT, 'Curso muy fácil, al estar en un país con su maestría o algo así estuvo bastante ocupado, fue virtual y de las 16 clases, solo tuvimos que conectarnos como a 8 clases y no revisó fuerte si lo entregó se sacó 100 básicamente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'f4601121752d56db0c3e1a389ffdb18455c324cbf111fec62a6d7c1e606334ea'::TEXT, ARRAY[981]::BIGINT[]),
    (136::BIGINT, 'El profesor hace la clase interesante, les recomiendo tener cuidado al momento de opinar sobre las lecturas porque se lo puede tomar un poco personal.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-03-06T00:00:00+00:00'::TIMESTAMPTZ, 'bf25021d5e48339c8fc18322e4ecd6f8c308f0eafec98c035779647ebeb91a74'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (136::BIGINT, 'Le gusta que los estudiantes participen. Es detallista así que en el proyecto a veces se pone en cosas por algo que no debería, pero ya si uno lo arregla más le pone el 100. Si no te gusta como filosofar y crear tu opinion de las cosas, no lo vas a disfrutar mucho.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2024-12-10T00:00:00+00:00'::TIMESTAMPTZ, '104d994232579804e92f1f8c323e7c27327e0b4f6c0a3caa961a6ca26f065996'::TEXT, ARRAY[2460]::BIGINT[]),
    (136::BIGINT, 'Excelente profesor, el curso es muy fácil. Eso si, hay que hacer bastantes trabajos, es recomendable llevar con gente conocida para hacer el proyecto.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, '2b69b5e29a676260549a418e5d4d546ba515095aee55027cc3062600f1d8251e'::TEXT, ARRAY[980]::BIGINT[]),
    (136::BIGINT, 'Curso muy izi. Deja trabajos casi todas las semanas pero solo es de dar la opinión.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, '109f1165e18c949afc98e35fa925e833810d0648a905227c17a9fd2284f46e39'::TEXT, ARRAY[980]::BIGINT[]),
    (136::BIGINT, 'El curso súper llevadero y muy interesante. En las clases se discuten temas muy importantes y se aprende un montón. Lo recomiendo al 100%'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Inspirador']::TEXT[], '2023-11-26T00:00:00+00:00'::TIMESTAMPTZ, '0fe6d711f57327fcb39574581e89b9d8371fe8a781d247e6cf0ade54608f8b1d'::TEXT, ARRAY[980]::BIGINT[]),
    (136::BIGINT, 'Es claro con las asignaciones del curso y ayuda al estudiante en el proceso. En general, hace que el curso sea bastante llevadero.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'd80c9328518d54810afbb25a8f76308656f0fc170162a06cb70f7ddbd70ffeea'::TEXT, ARRAY[980]::BIGINT[]),
    (136::BIGINT, 'El profe es tuanis y hace que el curso sea bastante interesante. El único problema que tuvo fue el de no entregar notas a tiempo y ser un poco desorganizado con las fechas, pero en realidad con entregar los trabajos se pasa muy fácil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Inspirador']::TEXT[], '2022-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'fa4203dbeba23d7160bef7fc91f130cd37da46e75026da55adccebc69bd410c7'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (136::BIGINT, 'Un curso llevadero, trabajos fáciles y hay que leer bastante. Cambia mucho las fechas del cronograma.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'c8f498474629c188e1ccdba6c63dc07ed4e163291c8d2eb76e022fa18718124e'::TEXT, ARRAY[2460]::BIGINT[]),
    (136::BIGINT, 'Buen profesor'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2022-10-14T00:00:00+00:00'::TIMESTAMPTZ, '73cc9c5b5c548d4df97edb30ba773b93ee11cdf5f4d0a97187bd9a882d95a8dd'::TEXT, ARRAY[981]::BIGINT[]),
    (136::BIGINT, 'Las clases son algo largas, hay que leer mucho, a veces el profe puede ser un poco desordenado y parece estar poco preparado para la clase, pero el curso es llevadero'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2022-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'c69b0de72f6af23d81c2d7872b5a93f7ccea0c1af29d6ffb6a1384275dfd4e47'::TEXT, ARRAY[3135]::BIGINT[]),
    (136::BIGINT, 'En virtual es un profe que aprovecha el tiempo, es muy relax, buena nota, desarrolla los temas super interesante y la verdad es un profe de mucha calidad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, '607ef1924f9bb6121a77c254b8755305797674c95e374d0801e1984463e1d26d'::TEXT, ARRAY[2460]::BIGINT[]),
    (136::BIGINT, 'Profe normal, un poco vago pero se pasa fácil, casi nunca hay clase de hecho, hay que leer mucho'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'd205c038cc7d955e148a1911207a4041fc1c363883c260c520bb8b75d6ec0d22'::TEXT, ARRAY[980]::BIGINT[]),
    (136::BIGINT, 'virtual, con solo meterlo tenga por seguro que ya lo pasa, a menos de que ud sea vago/a. El curso lo hace muy lindo y sólo basta con hacer las lecturas, comentar en clase y hacer el proyecto, el cual le da hasta más tiempo para que lo suba. Entiende al estduainate; calidad de profe....'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'c9232f3124fbebf9a7f433923eccda2e29a3a5b58558030000affc51bf4de40f'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (136::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2020-08-01T00:00:00+00:00'::TIMESTAMPTZ, '22c866241a70fbf7440fc774fa8b6d367cf272927be9182b6bbb71caec47b74d'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (136::BIGINT, 'Con este profe se aprende en seminario, lo que uno nunca creería posible'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'a7eb8741ca9b9626b4e54a625ea6239595ed78f3ccaa6714ea2e8e4cfb17ca2a'::TEXT, ARRAY[980]::BIGINT[]),
    (136::BIGINT, 'Hay que leer un poco para no llegar perdido a los trabajos en clase(que tienen su valor), el profe al inicio se ve un toque tímido, pero a final es todo pura vida! Lo recomiendo, se aprende bastante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'dd84934a395ac38262edc9dff0d9dcae9784675332108944883e82930a7a0667'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (136::BIGINT, 'El curso es aburrido pero él lo hace interesante. Hay que leer mucho y es algo estricto con el proyecto final, pero fuera de eso excelente profesor.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '5d87524b1da3f1e9165e63c59a6bc6322690ec898255e49b52e8ce89b72dc3d8'::TEXT, ARRAY[980]::BIGINT[]),
    (136::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'ca9ea8223205d20548d53db69b9bbcc065ccaee9ca65f87dbf442eb08d7ba2f5'::TEXT, ARRAY[981]::BIGINT[]),
    (136::BIGINT, 'Es una persona muy agradable. Es joven, por lo cual entiende al estudiante. Las clases no las hace largas, hay que leer bastante pero si va al día es fácil. Hace quizes de comprensión sencillos, estudios de caso(exámenes) un poco largos y fáciles porque se hacen en grupo. Excelente profesor 100% :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'af8d4fa709b933272a6b4350830894ebd1a11e85ae47338600a2a3648d1ad37a'::TEXT, ARRAY[981]::BIGINT[]),
    (136::BIGINT, 'El profe como persona es tuanis, el curso es aburridillo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, '402ad957b0dd6c51e8e4d3c4d8c7dec78ce831bd6d2b3ee3730e7bb6befe9391'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (136::BIGINT, 'Se pasa solo'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-05T00:00:00+00:00'::TIMESTAMPTZ, '66141791076b6285bb11c8dad41f03da8430e41c4ab59a36563912552147cd41'::TEXT, ARRAY[980, 2460]::BIGINT[]),
    (136::BIGINT, 'Mucho que leer pero si uno va al día pasa bien. Explica bastante claro'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, '049f215af46d310d185d83ffbd8d002b7499dec9bdf41ebb6c08a4186a3ea073'::TEXT, ARRAY[980]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
